17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
30	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
31	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.util.StringUtils;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
66	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
67	     * address shape rather than full RFC 5322 conformance.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    /**
116	     * Rejects an owner payload that is missing or blank in any required field. The response body's
117	     * {@code errors} array lists the name of each offending field.
118	     *
119	     * @param ownerFieldsDto the owner payload to validate
120	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
121	     */
122	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
123	        List<String> missingFields = new ArrayList<>();
124	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
131	            missingFields.add("address");
132	        }
133	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
134	            missingFields.add("city");
135	        }
136	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
137	            missingFields.add("telephone");
138	        }
139	        if (!missingFields.isEmpty()) {
140	            throw new RequiredFieldsMissingException(missingFields);
141	        }
142	    }
143	
144	    /**
145	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
146	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
147	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
148	     * followed by 8 to 15 digits.
149	     *
150	     * @param telephone the raw telephone value from the request
151	     * @return the E.164 telephone (e.g. {@code +61412345678})
152	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
153	     */
154	    private String normalizeTelephone(String telephone) {
155	        if (telephone == null) {
156	            throw new InvalidFieldsException(List.of("telephone"));
157	        }
158	        String trimmed = telephone.trim();
159	        boolean international = trimmed.startsWith("+");
160	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
161	        String digits;
162	        if (international) {
163	            digits = cleaned.substring(1);
164	        } else {
165	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
166	            digits = "61" + national;
167	        }
168	        if (!digits.matches("[0-9]{8,15}")) {
169	            throw new InvalidFieldsException(List.of("telephone"));
170	        }
171	        return "+" + digits;
172	    }
173	
174	    /**
175	     * Best-effort normalization of an existing owner's stored telephone into E.164 form for
176	     * duplicate comparison, returning {@code null} when the value cannot form valid E.164.
177	     *
178	     * @param telephone an existing stored telephone value, may be {@code null}
179	     * @return the E.164 form, or {@code null} when it cannot be normalized
180	     */
181	    private String toE164OrNull(String telephone) {
182	        if (telephone == null) {
183	            return null;
184	        }
185	        try {
186	            return normalizeTelephone(telephone);
187	        }
188	        catch (InvalidFieldsException ex) {
189	            return null;
190	        }
191	    }
192	
193	    /**
194	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
195	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
196	     * be a syntactically valid address; the accepted value is returned lower-cased.
197	     *
198	     * @param email the raw email value from the request, may be {@code null}
199	     * @return the lower-cased email, or {@code null} when none was supplied
200	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
201	     */
202	    private String normalizeEmail(String email) {
203	        if (email == null || email.isBlank()) {
204	            return null;
205	        }
206	        String trimmed = email.trim();
207	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
208	            throw new InvalidFieldsException(List.of("email"));
209	        }
210	        return trimmed.toLowerCase(Locale.ROOT);
211	    }
212	
213	    /**
214	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
215	     * owners' telephones are normalized the same way before comparison so differently-formatted
216	     * values representing the same number are treated as duplicates.
217	     *
218	     * @param telephone the normalized (E.164) telephone of the owner being created
219	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
220	     */
221	    private void requireUniqueTelephone(String telephone) {
222	        boolean taken = this.clinicService.findAllOwners().stream()
223	            .map(Owner::getTelephone)
224	            .map(this::toE164OrNull)
225	            .filter(existing -> existing != null)
226	            .anyMatch(telephone::equals);
227	        if (taken) {
228	            throw new DuplicateOwnerTelephoneException(telephone);
229	        }
230	    }
231	
232	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
233	    @Override
234	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
235	        validateRequiredFields(ownerFieldsDto);
236	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
237	        requireUniqueTelephone(telephone);
238	        String email = normalizeEmail(ownerFieldsDto.getEmail());
239	        HttpHeaders headers = new HttpHeaders();
240	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
241	        owner.setTelephone(telephone);
242	        owner.setEmail(email);
243	        if (owner.getRegistrationDate() == null) {
244	            owner.setRegistrationDate(LocalDate.now());
245	        }
246	        this.clinicService.saveOwner(owner);
247	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
248	        headers.setLocation(UriComponentsBuilder.newInstance()
249	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
250	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
256	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
257	        if (currentOwner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        currentOwner.setAddress(ownerFieldsDto.getAddress());
261	        currentOwner.setCity(ownerFieldsDto.getCity());
262	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
263	        currentOwner.setLastName(ownerFieldsDto.getLastName());
264	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
265	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
266	        this.clinicService.saveOwner(currentOwner);
267	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
268	    }
269	
270	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
271	    @Transactional
272	    @Override
273	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
274	        Owner owner = this.clinicService.findOwnerById(ownerId);
275	        if (owner == null) {
276	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	        }
278	        this.clinicService.deleteOwner(owner);
279	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
280	    }
281	
282	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
283	    @Override
284	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
285	        Owner owner = this.clinicService.findOwnerById(ownerId);
286	        if (owner == null) {
287	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
288	        }
289	        HttpHeaders headers = new HttpHeaders();
290	        Pet pet = petMapper.toPet(petFieldsDto);
291	        owner.setId(ownerId);
292	        pet.setOwner(owner);
293	        pet.getType().setName(null);
294	        this.clinicService.savePet(pet);
295	        PetDto petDto = petMapper.toPetDto(pet);
296	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
297	            .buildAndExpand(pet.getId()).toUri());
298	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
299	    }
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
304	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
305	        if (currentOwner != null) {
306	            Pet currentPet = this.clinicService.findPetById(petId);
307	            if (currentPet != null) {
308	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
309	                currentPet.setName(petFieldsDto.getName());
310	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
311	                this.clinicService.savePet(currentPet);
312	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
313	            }
314	        }
315	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
316	    }
317	
318	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
319	    @Override
320	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
321	        HttpHeaders headers = new HttpHeaders();
322	        Visit visit = visitMapper.toVisit(visitFieldsDto);
323	        Pet pet = new Pet();
324	        pet.setId(petId);
325	        visit.setPet(pet);
326	        this.clinicService.saveVisit(visit);
327	        VisitDto visitDto = visitMapper.toVisitDto(visit);
328	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
329	            .buildAndExpand(visit.getId()).toUri());
330	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
331	    }
332	
333	
334	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
335	    @Override
336	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
337	        Owner owner = this.clinicService.findOwnerById(ownerId);
338	        if (owner != null) {
339	            Pet pet = owner.getPet(petId);
340	            if (pet != null) {
341	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
342	            }
343	        }
344	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
345	    }
346	}
